pub fn extract_action_label(markup: &str) -> Option<String> {
    const PREFIX: &str = "[attribute kind=\"";
    const MIDDLE: &str = "\"]";
    const END: &str = "[/attribute]";

    let mut rest = markup;
    let mut answer = None;
    while !rest.is_empty() {
        let after_prefix = rest.strip_prefix(PREFIX)?;
        let kind_end = after_prefix.find(MIDDLE)?;
        let kind = &after_prefix[..kind_end];
        let after_header = &after_prefix[kind_end + MIDDLE.len()..];
        let value_end = after_header.find(END)?;
        let value = &after_header[..value_end];
        if kind == "action-label" && answer.is_none() {
            answer = Some(value.to_string());
        }
        rest = &after_header[value_end + END.len()..];
    }
    answer
}
